package java_program;

public class IfElseCondition {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int a =10;
		int b = 20;
		int c = 5;
		
		if( a>= b+c || a<b) {
			System.out.println("Condition True");
		}
		else {
			System.out.println("Condition false");
		}
	}

}
